// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    ERCDDAToken c;
    function setUp() public { c = new ERCDDAToken(0, "", ""); }

    function testFuzz_property(address caller, uint256 amount) public {
        vm.assume(caller != address(0));
        vm.assume(caller != address(this));

        uint256 mintAmount = bound(amount, 1, type(uint256).max / 2);
        vm.startPrank(address(this));
        c.mintToken(caller, mintAmount);
        vm.stopPrank();

        uint256 preTotal = c.totalSupply();

        vm.prank(caller);
        bool ok;
        try c.burn(amount) {
            ok = true;
        } catch {
            ok = false;
        }

        uint256 postTotal = c.totalSupply();

        assertTrue(postTotal == preTotal);
    }
}
